import { redirect } from 'next/navigation';

export default function ContactForm() {
  async function submitContact(formData: FormData) {
    'use server';

    const name = formData.get('name');
    const email = formData.get('email');
    const message = formData.get('message');

    // JavaScript validation in the server action
    if (!name || typeof name !== 'string' || name.trim() === '') {
      throw new Error('Validation Error: Name is required');
    }
    if (!email || typeof email !== 'string' || email.trim() === '') {
      throw new Error('Validation Error: Email is required');
    }
    if (!message || typeof message !== 'string' || message.trim() === '') {
      throw new Error('Validation Error: Message is required');
    }

    console.log('Contact form submitted:', { name, email, message });

    // In a real application, you would save this to a database
    // For now, we'll just redirect to home or show success (simulated)
    redirect('/');
  }

  return (
    <form action={submitContact} style={{ maxWidth: '400px', margin: '20px auto', display: 'flex', flexDirection: 'column', gap: '10px' }}>
      <h2>Contact Us</h2>

      <div style={{ display: 'flex', flexDirection: 'column' }}>
        <label htmlFor="name">Name:</label>
        <input type="text" id="name" name="name" required style={{ padding: '8px', marginTop: '4px' }} />
      </div>

      <div style={{ display: 'flex', flexDirection: 'column' }}>
        <label htmlFor="email">Email:</label>
        <input type="email" id="email" name="email" required style={{ padding: '8px', marginTop: '4px' }} />
      </div>

      <div style={{ display: 'flex', flexDirection: 'column' }}>
        <label htmlFor="message">Message:</label>
        <textarea id="message" name="message" rows={4} required style={{ padding: '8px', marginTop: '4px' }} />
      </div>

      <button type="submit" style={{ padding: '10px', backgroundColor: '#0070f3', color: 'white', border: 'none', cursor: 'pointer', marginTop: '10px' }}>
        Send Message
      </button>
    </form>
  );
}

